 25	 @Scheduled(fixedDelay = 60000) // Every 1 minute
 26	 public void syncAllSupplierStock() {
 27	 log.info("Starting scheduled stock sync for all suppliers");
 28	 
 29	 List<Supplier> activeSuppliers = supplierRepository.findByActiveTrue();
 30	 
 31	 for (Supplier supplier : activeSuppliers) {
 32	 try {
 33	 syncStockForSupplier(supplier);
 34	 } catch (Exception e) {
 35	 log.error("Failed to sync stock for supplier {}: {}", supplier.getName(), e.getMessage());
 36	 }
 37	 }
 38	 
 39	 log.info("Completed scheduled stock sync for {} suppliers", activeSuppliers.size());
 40	 }
 41	
 42	 public void syncStockForSupplier(Supplier supplier) {
 43	 log.info("Syncing stock for supplier: {}", supplier.getName());
 44	 
 45	 int updatedCount = 0;
 46	 try {
 47	 // Fetch latest products from supplier
 48	 List<SupplierProductDto> latest = productFetcherFactory.fetch(supplier);
 49	 if (latest == null || latest.isEmpty()) {
 50	 log.warn("No products returned from supplier {} during sync", supplier.getName());
 51	 return;
 52	 }
 53	
 54	 // Map by external id for quick lookup
 55	 java.util.Map<String, SupplierProductDto> byExternal = new java.util.HashMap<>();
 56	 for (SupplierProductDto dto : latest) {
 57	 if (dto.getExternalProductId() != null) {
 58	 byExternal.put(dto.getExternalProductId(), dto);
 59	 }
 60	 }
 61	
 62	 List<Product> products = productRepository.findBySupplierId(supplier.getId());
 63	 for (Product product : products) {
 64	 SupplierProductDto dto = byExternal.get(product.getExternalProductId());
 65	 if (dto != null) {
 66	 product.setSyncedStock(dto.getStock());
 67	 product.setLastFetched(LocalDateTime.now());
 68	 productRepository.save(product);
 69	 updatedCount++;
 70	 }
 71	 }
 72	 } catch (Exception e) {
 73	 log.error("Failed to fetch/update stock for supplier {}: {}", supplier.getName(), e.getMessage());
 74	 }
 75	 
 76	 log.info("Completed stock sync for supplier {} - {} products updated", supplier.getName(), updatedCount);
 77	 }
 78	}
