 31	 public ResponseEntity<Map<String, String>> uploadImage(@RequestParam("file") MultipartFile file) throws IOException {
 32	 ensureDirectories();
 33	
 34	 if (file.isEmpty()) {
 35	 return ResponseEntity.badRequest().body(Map.of("error", "Empty file"));
 36	 }
 37	
 38	 String original = file.getOriginalFilename() != null ? file.getOriginalFilename() : "image";
 39	 String extension = "";
 40	 int dot = original.lastIndexOf('.');
 41	 if (dot >= 0) {
 42	 extension = original.substring(dot);
 43	 }
 44	
 45	 String storedName = "img_" + UUID.randomUUID() + extension;
 46	 Path target = IMAGES_DIR.resolve(storedName);
 47	 Files.copy(file.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);
 48	
 49	 // Served by WebConfig as /uploads/** -> file:uploads/
 50	 String publicUrl = "/uploads/images/" + storedName;
 51	 return ResponseEntity.ok(Map.of("url", publicUrl, "filename", storedName));
 52	 }
 53	}
