 14	 getAllProducts(params?: {
 15	 category?: string;
 16	 supplier?: string;
 17	 search?: string;
 18	 sortBy?: string;
 19	 page?: number;
 20	 size?: number;
 21	 includeInactive?: boolean;
 22	 }): Observable<Product[]> {
 23	 let httpParams = new HttpParams();
 24	 if (params) {
 25	 Object.keys(params).forEach(key => {
 26	 const value = (params as any)[key];
 27	 if (value !== undefined && value !== null) {
 28	 httpParams = httpParams.append(key, value.toString());
 29	 }
 30	 });
 31	 }
 32	 return this.http.get<Product[]>(`${this.apiUrl}/products`, {
 33	 params: httpParams,
 34	 });
 35	 }
