 57	 // Match backend endpoints /activate and /deactivate
 58	 updateProductStatus(id: number, isActive: boolean): Observable<Product> {
 59	 const path = isActive ? "activate" : "deactivate";
 60	 return this.http.put<Product>(`${this.apiUrl}/products/${id}/${path}`, {});
