 76	 @PutMapping("/{id}")
 77	 @PreAuthorize("hasRole('ADMIN')")
 78	 public ResponseEntity<?> update(@PathVariable Long id, @RequestBody ProductDto dto) {
 79	 try {
 80	 // Basic validation
 81	 if (dto.getName() != null && dto.getName().trim().isEmpty()) {
 82	 return ResponseEntity.badRequest().body(Map.of("error", "Product name cannot be empty"));
 83	 }
 84	 if (dto.getDisplayedPrice() != null && dto.getDisplayedPrice() < 0) {
 85	 return ResponseEntity.badRequest().body(Map.of("error", "Price cannot be negative"));
 86	 }
 87	 if (dto.getSyncedStock() != null && dto.getSyncedStock() < 0) {
 88	 return ResponseEntity.badRequest().body(Map.of("error", "Stock cannot be negative"));
 89	 }
 90	
 91	 ProductDto updated = productService.updateProduct(id, dto);
 92	 return ResponseEntity.ok(updated);
 93	 } catch (ResourceNotFoundException e) {
 94	 return ResponseEntity.notFound().build();
 95	 } catch (Exception e) {
 96	 log.error("Error updating product {}: {}", id, e.getMessage());
 97	 return ResponseEntity.badRequest().body(Map.of("error", e.getMessage()));
 98	 }
 99	 }
