 55	 product.setDescription(supplierProduct.getDescription());
 56	 // Supplier price: the original price from supplier feed
 57	 product.setSupplierPrice(supplierProduct.getPrice());
 58	 // Displayed price: KEEP existing if already set by admin. If new product, default to supplier price.
 59	 if (product.getDisplayedPrice() == null) {
 60	 product.setDisplayedPrice(supplierProduct.getPrice());
 61	 }
