 157	 private String saveOrNormalizeImage(String value, Long supplierId, String externalId) {
 158	 try {
 159	 if (value.startsWith("http://") || value.startsWith("https://")) {
 160	 String ext = value.contains(".") ? value.substring(value.lastIndexOf('.') + 1) : "jpg";
 161	 Path dir = Paths.get("uploads", "images", String.valueOf(supplierId));
 162	 Files.createDirectories(dir);
 163	 Path out = dir.resolve((externalId != null ? externalId : String.valueOf(System.currentTimeMillis())) + "." + ext);
 164	 try (InputStream in = new URL(value).openStream()) {
 165	 Files.copy(in, out, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
 166	 }
 167	 return "/uploads/images/" + supplierId + "/" + out.getFileName();
 168	 }
 169	 // Filename or relative → normalize to uploads/images
 170	 value = value.replaceFirst("^/?(images/)?", "");
 171	 return "/uploads/images/" + value;
 172	 } catch (Exception e) {
 173	 log.warn("Failed to save image {}, reason: {}", value, e.getMessage());
 174	 return "/uploads/images/placeholder.jpg";
 175	 }
 176	 }
