 249	 /**
 250	 * Validate that product is available and has sufficient stock
 251	 */
 252	 private void validateProductAvailability(Product product, int requestedQuantity) {
 253	 if (!Boolean.TRUE.equals(product.getActive())) {
 254	 throw new IllegalStateException("Le produit " + product.getName() + " n'est plus disponible");
 255	 }
 256	 
 257	 Integer availableStock = product.getSyncedStock();
 258	 Integer reservedStock = product.getReservedStock() != null ? product.getReservedStock() : 0;
 259	 Integer actualAvailable = availableStock != null ? availableStock - reservedStock : 0;
 260	 
 261	 if (actualAvailable < requestedQuantity) {
 262	 throw new InsufficientStockException(String.format(
 263	 "Stock insuffisant pour %s. Demandé: %d, Disponible: %d",
 264	 product.getName(), requestedQuantity, actualAvailable
 265	 ));
 266	 }
 267	 }
