 99	 <ng-container matColumnDef="name">
 100	 <th mat-header-cell *matHeaderCellDef mat-sort-header>Name</th>
 101	 <td mat-cell *matCellDef="let product">{{ product.name }}</td>
 102	 </ng-container>
 103	
 104	 <!-- Price Column -->
 105	 <ng-container matColumnDef="price">
