 107	 <td mat-cell *matCellDef="let product">\${{ product.displayedPrice | number:'1.2-2' }}</td>
 108	 </ng-container>
 109	
 110	 <!-- Stock Column -->
 111	 <ng-container matColumnDef="stock">
 112	 <th mat-header-cell *matHeaderCellDef mat-sort-header>Stock</th>
 113	 <td mat-cell *matCellDef="let product">{{ product.syncedStock || 'N/A' }}</td>
 114	 </ng-container>
 115	
