 117	 <ng-container matColumnDef="status">
 118	 <th mat-header-cell *matHeaderCellDef mat-sort-header>Status</th>
 119	 <td mat-cell *matCellDef="let product">
 120	 <span [class]="'status-badge status-' + getProductStatus(product).toLowerCase()">
 121	 {{ getProductStatus(product) }}
 122	 </span>
 123	 </td>
 124	 </ng-container>
 125	
 126	 <!-- Actions Column -->
 127	 <ng-container matColumnDef="actions">
 128	 <th mat-header-cell *matHeaderCellDef>Actions</th>
 129	 <td mat-cell *matCellDef="let product">
 130	 <button mat-icon-button (click)="editProduct(product)" matTooltip="Edit Product">
 131	 <mat-icon>edit</mat-icon>
 132	 </button>
 133	 <button mat-icon-button (click)="approveProduct(product)" 
 134	 *ngIf="!isProductActive(product)"
 135	 matTooltip="Approve Product">
 136	 <mat-icon>check</mat-icon>
 137	 </button>
 138	 <button mat-icon-button (click)="rejectProduct(product)" 
 139	 *ngIf="!isProductActive(product)"
 140	 matTooltip="Reject Product">
 141	 <mat-icon>close</mat-icon>
 142	 </button>
 143	 <button mat-icon-button (click)="deactivateProduct(product)" 
 144	 *ngIf="isProductActive(product)"
 145	 matTooltip="Deactivate Product">
 146	 <mat-icon>block</mat-icon>
 147	 </button>
 148	 </td>
 149	 </ng-container>
 150	
 151	 <tr mat-header-row *matHeaderRowDef="displayedColumns"></tr>
 152	 <tr mat-row *matRowDef="let row; columns: displayedColumns;"></tr>
 153	 </table>
 154	
 155	 <mat-paginator [pageSizeOptions]="[10, 25, 50, 100]" 
 156	 showFirstLastButtons 
 157	 aria-label="Select page of products">
 158	 </mat-paginator>
 159	 </div>
 160	
 161	 <div *ngIf="!loading && filteredProducts.length === 0" class="no-products">
 162	 <mat-icon>inventory_2</mat-icon>
 163	 <h3>No products found</h3>
 164	 <p>No products match your current filters.</p>
 165	 </div>
 166	
 167	 <!-- Bulk Actions -->
 168	 <div *ngIf="selectedProducts.length > 0" class="bulk-actions">
 169	 <mat-card>
