 201	
 202	 <mat-form-field appearance="outline" class="half-width">
 203	 <mat-label>Category</mat-label>
 204	 <mat-select formControlName="categoryName" required>
 205	 <mat-option *ngFor="let category of categories" [value]="category.name">
 206	 {{ category.name }}
 207	 </mat-option>
 208	 </mat-select>
 209	 <mat-error *ngIf="productForm.get('categoryId')?.hasError('required')">
 210	 Category is required
 211	 </mat-error>
 212	 </mat-form-field>
 213	 </div>
 214	
 215	 <mat-form-field appearance="outline" class="full-width">
 216	 <mat-label>Description</mat-label>
 217	 <textarea matInput formControlName="description" rows="3"></textarea>
 218	 </mat-form-field>
 219	
 220	 <div class="form-row">
 221	 <mat-form-field appearance="outline" class="half-width">
 222	 <mat-label>Display Price</mat-label>
 223	 <input matInput type="number" formControlName="displayedPrice" required>
 224	 <mat-error *ngIf="productForm.get('displayedPrice')?.hasError('required')">
 225	 Display price is required
 226	 </mat-error>
 227	 </mat-form-field>
 228	
 229	 <mat-form-field appearance="outline" class="half-width">
 230	 <mat-label>Stock</mat-label>
 231	 <input matInput type="number" formControlName="syncedStock" required>
 232	 <mat-error *ngIf="productForm.get('syncedStock')?.hasError('required')">
 233	 Stock is required
 234	 </mat-error>
 235	 </mat-form-field>
 236	 </div>
 237	
 238	 <mat-checkbox formControlName="active">
 239	 Make product active (visible to customers)
 240	 </mat-checkbox>
 241	 </form>
 242	 </mat-dialog-content>
 243	 <mat-dialog-actions align="end">
 244	 <button mat-button mat-dialog-close>Cancel</button>
 245	 <button mat-raised-button color="primary" (click)="saveProduct()" [disabled]="productForm.invalid || saving">
 246	 <mat-spinner *ngIf="saving" diameter="20"></mat-spinner>
 247	 <span *ngIf="!saving">Save Changes</span>
 248	 </button>
 249	 </mat-dialog-actions>
 250	 </div>
 251	 </ng-template>
