 395	export class ProductApprovalComponent implements OnInit {
 396	 private productService = inject(ProductService);
 397	 private categoryService = inject(CategoryService);
 398	 private snackBar = inject(MatSnackBar);
 399	 private dialog = inject(MatDialog);
 400	 private fb = inject(FormBuilder);
 401	
 402	 @ViewChild('productEditDialog', { static: true }) productEditDialog!: TemplateRef<any>;
 403	
 404	 products: Product[] = [];
 405	 filteredProducts: Product[] = [];
 406	 categories: Category[] = [];
 407	 selectedProducts: Product[] = [];
 408	 loading = true;
 409	 saving = false;
 410	
 411	 // Filters
 412	 statusFilter = '';
 413	 searchTerm = '';
 414	
 415	 // Table
 416	 displayedColumns = ['image', 'name', 'price', 'stock', 'status', 'actions'];
 417	
 418	 // Form
 419	 productForm: FormGroup = this.fb.group({
 420	 name: ['', Validators.required],
 421	 description: [''],
 422	 categoryName: ['', Validators.required],
 423	 displayedPrice: ['', [Validators.required, Validators.min(0)]],
 424	 syncedStock: ['', [Validators.required, Validators.min(0)]],
 425	 active: [false]
 426	 });
 427	 
 428	 selectedProduct: Product | null = null;
 429	
 430	 ngOnInit(): void {
 431	 this.loadProducts();
 432	 this.loadCategories();
 433	 }
 434	
 435	 loadProducts(): void {
 436	 this.loading = true;
 437	 this.productService.getAllProducts({ includeInactive: true }).subscribe({
 438	 next: (products) => {
 439	 this.products = products;
 440	 this.applyFilters();
 441	 this.loading = false;
 442	 },
 443	 error: (error) => {
 444	 console.error('Error loading products:', error);
 445	 this.snackBar.open('Failed to load products', 'Close', { duration: 3000 });
 446	 this.loading = false;
 447	 }
 448	 });
 449	 }
 450	
 451	 loadCategories(): void {
 452	 this.categoryService.getCategories().subscribe({
 453	 next: (categories: any[]) => {
 454	 this.categories = categories;
 455	 },
 456	 error: (error: any) => {
 457	 console.error('Error loading categories:', error);
 458	 }
 459	 });
 460	 }
 461	
 462	 applyFilters(): void {
 463	 this.filteredProducts = this.products.filter(product => {
 464	 // Search filter
 465	 if (this.searchTerm && !product.name.toLowerCase().includes(this.searchTerm.toLowerCase()) &&
 466	 !product.description?.toLowerCase().includes(this.searchTerm.toLowerCase())) {
 467	 return false;
 468	 }
 469	
 470	 // Status filter - simplified for now
 471	 if (this.statusFilter === 'PENDING' && this.isProductActive(product)) {
 472	 return false;
 473	 }
 474	 if (this.statusFilter === 'APPROVED' && !this.isProductActive(product)) {
 475	 return false;
 476	 }
 477	
 478	 return true;
 479	 });
 480	 }
 481	
 482	 isProductActive(product: Product): boolean {
 483	 return Boolean(product.active);
 484	 }
 485	
 486	 getProductStatus(product: Product): string {
 487	 return this.isProductActive(product) ? 'ACTIVE' : 'PENDING';
 488	 }
 489	
 490	 resolveImageUrl(url?: string): string | undefined {
 491	 if (!url) return undefined;
 492	 if (url.startsWith('data:image')) return url;
 493	 if (url.startsWith('/api/') || url.startsWith('/uploads/') || url.startsWith('/images/')) {
 494	 return `${environment.apiUrl}${url}`;
 495	 }
 496	 const clean = url.replace(/^\/?(images\/?)/, '');
 497	 return `${environment.apiUrl}/uploads/images/${clean}`;
 498	 }
 499	
 500	 editProduct(product: Product): void {
 501	 this.selectedProduct = product;
 502	 this.productForm.patchValue({
 503	 name: product.name,
 504	 description: product.description || '',
 505	 categoryName: (product as any).categoryName || '',
 506	 displayedPrice: product.displayedPrice,
 507	 syncedStock: product.syncedStock || 0,
 508	 active: product.active || false
 509	 });
 510	
 511	 this.dialog.open(this.productEditDialog, {
 512	 width: '600px',
 513	 disableClose: true
 514	 });
 515	 }
 516	
 517	 saveProduct(): void {
 518	 if (this.productForm.invalid || !this.selectedProduct) return;
 519	
 520	 this.saving = true;
 521	 const formValue = this.productForm.value;
 522	 
 523	 const updatedProduct = {
 524	 ...formValue,
 525	 id: this.selectedProduct.id
 526	 } as any;
 527	
 528	 // ensure we only send fields the backend expects and do not send id in body
 529	 const payload = {
 530	 name: updatedProduct.name,
 531	 description: updatedProduct.description,
 532	 categoryName: updatedProduct.categoryName,
 533	 displayedPrice: updatedProduct.displayedPrice,
 534	 syncedStock: updatedProduct.syncedStock,
 535	 active: updatedProduct.active
 536	 };
 537	
 538	 this.productService.updateProduct(this.selectedProduct.id, payload).subscribe({
 539	 next: (product) => {
 540	 this.snackBar.open('Product updated successfully', 'Close', { duration: 3000 });
 541	 this.loadProducts();
 542	 this.dialog.closeAll();
 543	 this.saving = false;
 544	 },
 545	 error: (error) => {
 546	 console.error('Error updating product:', error);
 547	 const msg = error?.error?.message || 'Failed to update product';
 548	 this.snackBar.open(msg, 'Close', { duration: 4000 });
 549	 this.saving = false;
 550	 }
 551	 });
 552	 }
 553	
 554	 approveProduct(product: Product): void {
 555	 this.productService.approveProduct(product.id).subscribe({
 556	 next: () => {
 557	 this.snackBar.open('Product approved successfully', 'Close', { duration: 3000 });
 558	 this.loadProducts();
 559	 },
 560	 error: (error) => {
 561	 console.error('Error approving product:', error);
 562	 this.snackBar.open('Failed to approve product', 'Close', { duration: 3000 });
 563	 }
 564	 });
 565	 }
 566	
 567	 rejectProduct(product: Product): void {
 568	 this.productService.rejectProduct(product.id).subscribe({
 569	 next: () => {
 570	 this.snackBar.open('Product rejected successfully', 'Close', { duration: 3000 });
 571	 this.loadProducts();
 572	 },
 573	 error: (error) => {
 574	 console.error('Error rejecting product:', error);
 575	 this.snackBar.open('Failed to reject product', 'Close', { duration: 3000 });
 576	 }
 577	 });
 578	 }
 579	
 580	 deactivateProduct(product: Product): void {
 581	 this.productService.updateProductStatus(product.id, false).subscribe({
 582	 next: () => {
 583	 this.snackBar.open('Product deactivated successfully', 'Close', { duration: 3000 });
 584	 this.loadProducts();
 585	 },
 586	 error: (error) => {
 587	 console.error('Error deactivating product:', error);
 588	 this.snackBar.open('Failed to deactivate product', 'Close', { duration: 3000 });
 589	 }
 590	 });
 591	 }
 592	
 593	 bulkApprove(): void {
 594	 const ids = this.selectedProducts.map(p => p.id);
 595	 this.productService.approveMultipleProducts(ids).subscribe({
 596	 next: () => {
 597	 this.snackBar.open(`${ids.length} products approved successfully`, 'Close', { duration: 3000 });
 598	 this.selectedProducts = [];
 599	 this.loadProducts();
 600	 },
 601	 error: (error) => {
 602	 console.error('Error approving products:', error);
 603	 this.snackBar.open('Failed to approve products', 'Close', { duration: 3000 });
 604	 }
 605	 });
 606	 }
 607	
 608	 bulkReject(): void {
 609	 // For bulk reject, we'll need to call individual reject for each product
 610	 // since the backend doesn't have a bulk reject endpoint
 611	 const rejectPromises = this.selectedProducts.map(product => 
 612	 this.productService.rejectProduct(product.id).toPromise()
 613	 );
 614	
 615	 Promise.all(rejectPromises).then(() => {
 616	 this.snackBar.open(`${this.selectedProducts.length} products rejected successfully`, 'Close', { duration: 3000 });
 617	 this.selectedProducts = [];
 618	 this.loadProducts();
 619	 }).catch((error) => {
 620	 console.error('Error rejecting products:', error);
 621	 this.snackBar.open('Failed to reject some products', 'Close', { duration: 3000 });
 622	 });
 623	 }
 624	}
